mapper.select:
SELECT t.snapshot_json FROM fin_ex_wb_task_t t
JOIN fin_ex_wb_task_ext_value_t x ON x.task_id=t.task_id AND x.field_key=#{field} AND x.schema_version=#{schemaVersion}
WHERE tenant_id=#{tenant} AND deleted_at IS NULL AND (owner_user_id=#{user} OR EXISTS (SELECT 1 FROM fin_ex_wb_task_member_t m WHERE m.task_id=t.task_id AND m.user_id=#{user}))
 AND t.source_app_id=#{app}
 AND t.owner_user_id=#{user}
 AND EXISTS (SELECT 1 FROM fin_ex_wb_task_member_t p WHERE p.task_id=t.task_id AND p.user_id=#{user})
 AND x.text_value=#{text} AND x.number_value=#{number}
 AND x.time_value=#{time} AND x.bool_value=#{bool}
 AND x.text_value ILIKE #{searchText} ESCAPE '!'
 AND status=#{status} AND (l1_key=#{l1} OR l1_name=#{l1}) AND l2_key=#{l2} AND l3_key=#{l3}
ORDER BY
x.text_value
    x.number_valuex.time_value
    x.bool_value DESC,
t.creation_date DESC,t.task_id LIMIT #{limit} OFFSET #{offset}

SELECT p.operation_id,p.part_order,p.part_json FROM fin_ex_wb_task_op_part_t p WHERE p.task_id=#{taskId} AND p.operation_id IN
(SELECT operation_id FROM fin_ex_wb_task_operation_t WHERE task_id=#{taskId} AND scope_key=#{scope}
ORDER BY creation_date,operation_id LIMIT #{limit} OFFSET #{offset}) ORDER BY p.operation_id,p.part_order
